import {Module} from '@nestjs/common';
import {FeatureService} from './feature.service';
@Module({providers: [FeatureService], exports: [FeatureService]})
export class FeatureModule {}

import {Controller, Get, Param} from '@nestjs/common';
@Controller('items')
export class ItemsController {
  @Get(':id')
  find(@Param('id') id: string): void {}
}

import {Module} from '@nestjs/common';
import {A} from './a';
@Module({imports: process.env.FEATURE ? [A] : []})
export class ConditionalModule {}

import {Inject, Injectable} from '@nestjs/common';
@Injectable()
export class TokenService {
  use(@Inject(process.env.TOKEN || 'fallback') value: string): void {}
}

import {Module} from '@nestjs/common';
@Module({providers: [{provide: 'CLOCK', useFactory: () => Date.now()}]})
export class FactoryModule {}

import {Module} from '@nestjs/common';
const build = ({providers = []} = {}) => ({providers});
@Module(build())
export class OptionsModule {}
